const items = $input.all();
const rows = items.map(i => i.json);
const dateStr = new Date().toISOString().split('T')[0];

// Group by project
const grouped = {};
for (const row of rows) {
  const project = row.display_name || 'Unknown';
  if (!grouped[project]) {
    grouped[project] = [];
  }
  grouped[project].push(row);
}

let md = `# Weekly Personal Roundup - ${dateStr}\n\n`;
md += `**${rows.length} opportunities across ${Object.keys(grouped).length} categories**\n\n`;

if (rows.length === 0) {
  md += '_No new personal opportunities discovered this week._\n';
} else {
  for (const [project, opps] of Object.entries(grouped)) {
    md += `## ${project}\n\n`;
    for (const opp of opps) {
      const deadline = opp.deadline ? new Date(opp.deadline).toISOString().split('T')[0] : 'No deadline';
      const score = opp.relevance_score != null ? ` (relevance: ${opp.relevance_score})` : '';
      md += `### ${opp.title || 'Untitled'}${score}\n\n`;
      if (opp.funder) md += `- **Funder:** ${opp.funder}\n`;
      if (opp.region) md += `- **Region:** ${opp.region}\n`;
      md += `- **Deadline:** ${deadline}\n`;
      if (opp.url) md += `- **Link:** ${opp.url}\n`;
      if (opp.summary) md += `\n${opp.summary}\n`;
      md += '\n';
    }
  }
}

return [{ json: { markdown: md, dateStr, count: rows.length } }];
